def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    b_idx, winner_idx, loser_idx = (objective[:, :, None] < objective[:, None, :]).nonzero(as_tuple=True)
    if b_idx.numel() == 0:
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'pairwise_gap_linear_clamp_002', 'weight_family': 'gap_linear'})
    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]
    gap_pos = gap.clamp(min=0.0)
    clamp_lo = float(extra.get('clamp_lo', 0.25))
    clamp_hi = float(extra.get('clamp_hi', 4.0))
    weight = gap_pos.clamp(min=clamp_lo, max=clamp_hi)
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'pairwise_gap_linear_clamp_002', 'weight_family': 'gap_linear'})
